"""Ajustes de projeto do Bambu Studio (Metadata/project_settings.config) para a Bambu Lab A1.

Por que o 3MF precisa disto (18/11/2026): o Bambu Studio trata um 3MF do Bambu sem
project_settings.config como "gerado por versão antiga" e carrega só a geometria
(Plater.cpp, load_files: ramo `load_config && config_loaded.empty()`); o usuário viu o aviso
"The 3mf was generated by an old version of Bambu Studio, loading geometry data only".

Como é gerado, com o Bambu Studio instalado (observado em 17-18/11, versão 02.07.01.57):
- a CLI exporta um projeto de um cubo com os perfis de sistema; o project_settings exportado
  traz os nomes dos perfis, mas valores genéricos (bico 0,2 saía com linha de 0,4 e camada de
  0,2), então os valores dos perfis resolvidos (com "inherits") são copiados por cima;
- a CLI descarta filamentos não usados (fica 1): as listas de filamento são duplicadas e as
  cores ficam branco (1) e preto (2).
O resultado fica em cache em prototipo/.cache/ (fora do git: são valores dos perfis do Bambu).
Volumes de purga são suposição (o Bambu recalcula em "Flushing volumes").
"""
import json
import subprocess
import sys
import tempfile
import zipfile
from pathlib import Path

EXE = Path(r'C:/Program Files/Bambu Studio/bambu-studio.exe')
PERFIS = EXE.parent / 'resources/profiles/BBL'
CACHE = Path(__file__).parent / '.cache'
PURGA_SUPOSTA = ['0', '200', '600', '0']   # branco->preto, preto->branco (mm3), suposição
CORES = ['#FFFFFF', '#000000']
A1 = {
    '0.2': ('Bambu Lab A1 0.2 nozzle', '0.10mm Standard @BBL A1 0.2 nozzle', 'Bambu PLA Basic @BBL A1 0.2 nozzle'),
    '0.4': ('Bambu Lab A1 0.4 nozzle', '0.20mm Standard @BBL A1', 'Bambu PLA Basic @BBL A1'),
}
META = {'name', 'from', 'inherits', 'setting_id', 'instantiation', 'type', 'version', 'filament_id',
        'print_settings_id', 'printer_settings_id', 'filament_settings_id', 'filename_format',
        'compatible_printers', 'compatible_printers_condition', 'compatible_prints', 'compatible_prints_condition'}


def resolver(pasta, nome):
    """Perfil de sistema com a cadeia de "inherits" aplicada."""
    d = json.loads((PERFIS / pasta / f'{nome}.json').read_text(encoding='utf-8'))
    pai = d.pop('inherits', None)
    base = resolver(pasta, pai) if pai else {}
    base.update(d)
    return base


def cli(args, limite_s=300, tentativas=2):
    """Roda a CLI com tempo limite. Observado em 17/11: uma execução travou sem CPU por 10 min."""
    for n in range(1, tentativas + 1):
        try:
            return subprocess.run([str(EXE), *args], capture_output=True, text=True, timeout=limite_s).returncode
        except subprocess.TimeoutExpired:
            print(f'CLI do Bambu passou de {limite_s}s (tentativa {n}/{tentativas})', file=sys.stderr)
    return -999


def _cubo_3mf(caminho):
    """3MF genérico (sem metadados do Bambu) com um cubo de 10 mm: só serve para a exportação."""
    v = [(x, y, z) for z in (0, 10) for y in (0, 10) for x in (0, 10)]
    f = [(0, 2, 1), (1, 2, 3), (4, 5, 6), (5, 7, 6), (0, 1, 4), (1, 5, 4),
         (2, 6, 3), (3, 6, 7), (0, 4, 2), (2, 4, 6), (1, 3, 5), (3, 7, 5)]
    vs = ''.join(f'<vertex x="{x + 120}" y="{y + 120}" z="{z}"/>' for x, y, z in v)
    ts = ''.join(f'<triangle v1="{a}" v2="{b}" v3="{c}"/>' for a, b, c in f)
    modelo = ('<?xml version="1.0" encoding="UTF-8"?><model unit="millimeter" '
              'xmlns="http://schemas.microsoft.com/3dmanufacturing/core/2015/02"><resources>'
              f'<object id="1" type="model"><mesh><vertices>{vs}</vertices><triangles>{ts}</triangles></mesh></object>'
              '</resources><build><item objectid="1"/></build></model>')
    with zipfile.ZipFile(caminho, 'w', zipfile.ZIP_DEFLATED) as z:
        z.writestr('[Content_Types].xml', '<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="model" ContentType="application/vnd.ms-package.3dmanufacturing-3dmodel+xml"/></Types>')
        z.writestr('_rels/.rels', '<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Target="/3D/3dmodel.model" Id="rel0" Type="http://schemas.microsoft.com/3dmanufacturing/2013/01/3dmodel"/></Relationships>')
        z.writestr('3D/3dmodel.model', modelo)


def project_settings(maquina, processo, filamento, usar_cache=True):
    """project_settings.config (dict) com 2 filamentos, branco e preto, para esses perfis.

    Retorna (config, quantas chaves vieram do perfil resolvido).
    """
    chave = f'{maquina}|{processo}|{filamento}'.replace('@', '').replace(' ', '_').replace('|', '__')
    arq = CACHE / f'project_settings-{chave}.json'
    if usar_cache and arq.exists():
        d = json.loads(arq.read_text(encoding='utf-8'))
        return d['config'], d['chaves_do_perfil']
    if not EXE.exists():
        raise FileNotFoundError(f'Bambu Studio não encontrado em {EXE}')
    tmp = Path(tempfile.mkdtemp(prefix='perfil_'))
    cubo = tmp / 'cubo.3mf'
    _cubo_3mf(cubo)
    fil = PERFIS / 'filament' / f'{filamento}.json'
    rc = cli(['--outputdir', str(tmp), '--export-3mf', 'exportado.3mf',
              '--load-settings', f'{PERFIS / "machine" / (maquina + ".json")};{PERFIS / "process" / (processo + ".json")}',
              '--load-filaments', f'{fil};{fil}', str(cubo)])
    exportado = tmp / 'exportado.3mf'
    if rc != 0 or not exportado.exists():
        raise RuntimeError(f'exportação de perfil pela CLI do Bambu falhou: {rc}')
    proj = json.loads(zipfile.ZipFile(exportado).read('Metadata/project_settings.config'))
    trocados = 0
    for tipo, nome in (('machine', maquina), ('process', processo), ('filament', filamento)):
        for k, v in resolver(tipo, nome).items():
            if k in proj and k not in META and proj[k] != v:
                proj[k] = v
                trocados += 1
    proj['enable_prime_tower'] = resolver('process', processo).get('enable_prime_tower', '1')
    chaves_fil = set(resolver('filament', filamento)) | {'filament_settings_id', 'filament_colour', 'filament_ids'}
    for k, v in list(proj.items()):
        if k in chaves_fil and isinstance(v, list) and len(v) == 1:
            proj[k] = v * 2
    proj['filament_colour'] = list(CORES)
    proj['flush_volumes_matrix'] = list(PURGA_SUPOSTA)
    if isinstance(proj.get('flush_volumes_vector'), list) and len(proj['flush_volumes_vector']) == 2:
        proj['flush_volumes_vector'] = proj['flush_volumes_vector'] * 2
    CACHE.mkdir(exist_ok=True)
    arq.write_text(json.dumps({'perfis': [maquina, processo, filamento], 'chaves_do_perfil': trocados,
                               'config': proj}, ensure_ascii=False), encoding='utf-8')
    return proj, trocados


def para_bico(bico):
    """Perfis de sistema da A1 para o bico (0,2 ou 0,4) e o project_settings correspondente."""
    perfis = A1[f'{float(bico):.1f}']
    return perfis, project_settings(*perfis)[0]
